"use client"

import React from "react"
import type { ReactNode } from "react"
import { Tabs, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { ExtendedTabs } from "@/components/blocks/navigation/ExtendedTabs"

/** One tab of a {@link CodeConsole} (e.g. "Test case", "Result"). */
export interface CodeConsoleTab {
    /** Stable tab id. */
    key: string
    /** Tab label. */
    label: ReactNode
    /** Panel content shown when this tab is selected. */
    content: ReactNode
}

/** Props for the {@link CodeConsole} block. */
export interface CodeConsoleProps extends WithClassNames<undefined> {
    /** Accessible label for the tab list. */
    ariaLabel: string
    /** The console tabs, in order. */
    tabs: Array<CodeConsoleTab>
    /** Selected tab id (controlled). */
    selectedTab: string
    /** Fired with the newly selected tab id. */
    onSelectTab: (key: string) => void
    /** Right-aligned action controls in the footer bar (e.g. Run / Submit). */
    actions: ReactNode
    /** Optional muted hint shown at the left of the footer bar. */
    hint?: ReactNode
}

/**
 * The bottom CONSOLE of a code workspace: a tab strip ({@link ExtendedTabs}) over
 * a scrollable panel, capped by a footer action bar (Run / Submit). Sits under an
 * editor, delineated by a top border; the block owns the shell (tabs ┬╖ scroll ┬╖
 * footer seam) so a feature only feeds tab content + the action controls. The
 * LeetCode-style console pattern ΓÇö testcases and results in tabs, actions pinned.
 *
 * @param props - {@link CodeConsoleProps}
 * @see Story: .storybook/stories/blocks/code/CodeConsole/CodeConsole.stories
 */
export const CodeConsole = ({
    ariaLabel,
    tabs,
    selectedTab,
    onSelectTab,
    actions,
    hint,
    className,
}: CodeConsoleProps) => {
    const active = tabs.find((tab) => tab.key === selectedTab) ?? tabs[0]

    return (
        <div className={cn("flex min-h-0 flex-col border-t border-default bg-surface", className)}>
            <div className="px-3 pt-1">
                <ExtendedTabs selectedKey={selectedTab} onSelectionChange={onSelectTab}>
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={ariaLabel}>
                            {tabs.map((tab) => (
                                <Tabs.Tab key={tab.key} id={tab.key}>
                                    {tab.label}
                                    <Tabs.Indicator />
                                </Tabs.Tab>
                            ))}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </ExtendedTabs>
            </div>

            <div className="min-h-0 flex-1 overflow-auto p-3">
                {active?.content}
            </div>

            <div className="flex items-center justify-between gap-3 border-t border-default px-3 py-2">
                {hint ? <span className="text-xs text-muted">{hint}</span> : <span />}
                <div className="flex items-center gap-2">{actions}</div>
            </div>
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/** Semantic tone of one IO row's label (drives the label colour only). */
export type IORowTone = "default" | "success" | "danger"

/** One labelled monospace block inside an {@link IOExampleCard}. */
export interface IOExampleRow {
    /** Stable key. */
    key: string
    /** Small muted label above the value (e.g. "Input", "Expected"). */
    label: ReactNode
    /** The literal value, rendered monospace and pre-wrapped. */
    value: string
    /** Label tone ΓÇö `success`/`danger` tint the label for a expected-vs-got diff. */
    tone?: IORowTone
}

/** Props for the {@link IOExampleCard} block. */
export interface IOExampleCardProps {
    /** The labelled blocks, in order ΓÇö separated by a dashed inset rule. */
    rows: Array<IOExampleRow>
}

/** Label colour per tone. */
const TONE_CLASS: Record<IORowTone, string> = {
    default: "text-muted",
    success: "text-success",
    danger: "text-danger",
}

/**
 * A bounded card that renders one or more LABELLED monospace blocks ΓÇö a sample
 * testcase (input ΓåÆ output), or a failed-case diff (input ┬╖ expected ┬╖ got with
 * tinted labels). Replaces the hand-rolled `<pre className="bg-default-100">`
 * scattered across the coding surfaces so every IO block reads the same: a small
 * muted label over a mono, pre-wrapped value, rows split by a dashed inset rule.
 * Presentational + props-only.
 *
 * @param props - {@link IOExampleCardProps}
 * @see Story: .storybook/stories/blocks/code/IOExampleCard/IOExampleCard.stories
 */
export const IOExampleCard = ({ rows}: IOExampleCardProps) => {
    return (
        <div className={"overflow-hidden rounded-3xl border border-default bg-surface"}>
            {rows.map((row, index) => (
                <div
                    key={row.key}
                    className={cn("px-3 py-2", index > 0 && "border-t border-dashed border-default")}
                >
                    <div className={cn("text-xs font-medium", TONE_CLASS[row.tone ?? "default"])}>
                        {row.label}
                    </div>
                    <pre className="mt-1 whitespace-pre-wrap break-words font-mono text-sm text-foreground">
                        {row.value}
                    </pre>
                </div>
            ))}
        </div>
    )
}

"use client"

import React from "react"
import {
    SandpackProvider,
    SandpackLayout,
    SandpackCodeEditor,
    SandpackPreview,
    SandpackFileExplorer,
} from "@codesandbox/sandpack-react"
import type { SandpackFiles, SandpackTheme } from "@codesandbox/sandpack-react"

const sharedFont = {
    body: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
    mono: "'Fira Code', 'Cascadia Code', 'JetBrains Mono', monospace",
    size: "13px",
    lineHeight: "1.6",
}

/** Editor dark theme ΓÇö surface1 matches the platform page background to blend in. */
const darkTheme: SandpackTheme = {
    colors: {
        surface1: "oklch(12.00% 0.0033 185.90)",
        surface2: "oklch(16.00% 0.0033 185.90)",
        surface3: "oklch(22.00% 0.0033 185.90)",
        clickable: "#6b7280",
        base: "#d1d5db",
        disabled: "#4b5563",
        hover: "#e5e7eb",
        accent: "#2dd4bf",
        error: "#f87171",
        errorSurface: "#1f1212",
    },
    syntax: {
        plain: "#e5e7eb",
        comment: { color: "#6b7280", fontStyle: "italic" },
        keyword: "#c084fc",
        tag: "#f472b6",
        punctuation: "#9ca3af",
        definition: "#60a5fa",
        property: "#34d399",
        static: "#fbbf24",
        string: "#86efac",
    },
    font: sharedFont,
}

/** Editor light theme ΓÇö surface1 matches the platform page background to blend in. */
const lightTheme: SandpackTheme = {
    colors: {
        surface1: "oklch(97.02% 0.0033 185.90)",
        surface2: "oklch(94.00% 0.0033 185.90)",
        surface3: "oklch(90.00% 0.0033 185.90)",
        clickable: "#71717a",
        base: "#27272a",
        disabled: "#a1a1aa",
        hover: "#18181b",
        accent: "#0d9488",
        error: "#dc2626",
        errorSurface: "#fef2f2",
    },
    syntax: {
        plain: "#27272a",
        comment: { color: "#a1a1aa", fontStyle: "italic" },
        keyword: "#9333ea",
        tag: "#db2777",
        punctuation: "#52525b",
        definition: "#2563eb",
        property: "#059669",
        static: "#b45309",
        string: "#15803d",
    },
    font: sharedFont,
}

/** Props for {@link SandpackPanel}. */
export interface SandpackPanelProps {
    /** Assembled files map (stubs + github files + dynamic overrides). */
    files: SandpackFiles
    /** Extra npm dependencies merged from the lesson's package.json. */
    dependencies?: Record<string, string>
    /** When true, use the dark editor theme (follows the platform theme). */
    isDark?: boolean
}

/**
 * External resources injected into the preview iframe by Sandpack itself
 * (the bundler ignores <script>/<link> tags inside index.html). Loads Tailwind
 * v4 utilities (runtime DOM scan) + HeroUI v3 compiled styles via CDN.
 */
const EXTERNAL_RESOURCES = [
    "https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4",
    "https://cdn.jsdelivr.net/npm/@heroui/styles@3/dist/heroui.min.css",
]

/** Live in-browser React sandbox (Sandpack) previewing the lesson's code files. */
export const SandpackPanel = ({ files, dependencies = {}, isDark = true}: SandpackPanelProps) => (
    <div>
        <SandpackProvider
            template="react-ts"
            theme={isDark ? darkTheme : lightTheme}
            files={files}
            customSetup={{ dependencies }}
            options={{
                recompileMode: "delayed",
                recompileDelay: 600,
                externalResources: EXTERNAL_RESOURCES,
                // load the embedded preview at /?sandbox=1 so lesson frontends that
                // split into Local/Sandbox render the multi-client Sandbox content;
                // frontends without the split simply ignore the query param.
                startRoute: "/?sandbox=1",
            }}
        >
            <SandpackLayout style={{ border: "none", borderRadius: 0, minHeight: 520, width: "100%" }}>
                {/* left half ΓÇö source: file tree + code editor */}
                <SandpackFileExplorer style={{ width: 190, height: 520 }} />
                <SandpackCodeEditor showLineNumbers showTabs={false} showReadOnly={false} style={{ flex: 1, height: 520 }} />
                {/* right half ΓÇö live UI preview */}
                <SandpackPreview showNavigator={false} showOpenInCodeSandbox style={{ flex: 1, height: 520 }} />
            </SandpackLayout>
        </SandpackProvider>
    </div>
)

"use client"

import React, { useEffect, useState } from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import { CheckIcon, XIcon } from "@phosphor-icons/react"
import { IOExampleCard } from "@/components/blocks/code/IOExampleCard"

/** One testcase outcome shown as a selectable pill + (sample) IO detail. */
export interface TestCaseResult {
    /** Stable key. */
    key: string
    /** Pill label (e.g. "Case 1"). */
    label: ReactNode
    /** Whether this case passed. */
    passed: boolean
    /** Sample cases carry IO; hidden cases show only the verdict pill. */
    isSample: boolean
    /** Sample-only: the stdin fed to the program. */
    input?: string | null
    /** Sample-only: the expected stdout. */
    expectedOutput?: string | null
    /** Sample-only: the program's actual stdout. */
    got?: string | null
}

/** Localised labels for the selected-case IO rows (caller passes translations). */
export interface TestCaseResultLabels {
    /** Label above the input value. */
    input: ReactNode
    /** Label above the expected value. */
    expected: ReactNode
    /** Label above the actual (got) value. */
    got: ReactNode
    /** Note shown when the selected case is a hidden (non-sample) case. */
    hidden: ReactNode
}

/** Props for the {@link TestCaseResultGrid} block. */
export interface TestCaseResultGridProps {
    /** The per-case outcomes, in evaluation order. */
    cases: Array<TestCaseResult>
    /** Localised labels for the selected sample case's IO rows. */
    labels: TestCaseResultLabels
}

/** Index of the first failing case, or 0 when all passed / empty. */
const firstFailingIndex = (cases: Array<TestCaseResult>): number => {
    const index = cases.findIndex((testcase) => !testcase.passed)
    return index >= 0 ? index : 0
}

/**
 * Renders a judged submission's PER-CASE outcome: a wrap of selectable pills
 * (Case N with a Γ£ô/Γ£ò glyph, tinted pass/fail) over the selected case's detail.
 * A sample case expands to an {@link IOExampleCard} (input ┬╖ expected ┬╖ got, with
 * the mismatch tinted on a failure); a hidden case shows only a muted note (its
 * IO never leaves the server). Selection defaults to the FIRST FAILING case so a
 * learner lands straight on what broke. Feeds off the decoded `perCaseResults`
 * the API already returns ΓÇö data the old UI discarded.
 *
 * @param props - {@link TestCaseResultGridProps}
 * @see Story: .storybook/stories/blocks/code/TestCaseResultGrid/TestCaseResultGrid.stories
 */
export const TestCaseResultGrid = ({ cases, labels}: TestCaseResultGridProps) => {
    const [selected, setSelected] = useState<number>(() => firstFailingIndex(cases))

    // re-home the selection on the first failing case whenever the result set changes
    // (a new submission arrives) so the pane never points at a stale index.
    useEffect(() => {
        setSelected(firstFailingIndex(cases))
    }, [cases])

    if (cases.length === 0) {
        return null
    }

    const active = cases[Math.min(selected, cases.length - 1)]

    return (
        <div className={"flex flex-col gap-3"}>
            <div className="flex flex-wrap gap-2">
                {cases.map((testcase, index) => {
                    const isActive = index === Math.min(selected, cases.length - 1)
                    return (
                        <button
                            key={testcase.key}
                            type="button"
                            onClick={() => setSelected(index)}
                            className={cn(
                                "flex items-center gap-2 rounded-lg px-3 py-1 text-xs font-medium outline-none transition-colors",
                                "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent",
                                testcase.passed
                                    ? "bg-success-soft text-success-soft-foreground"
                                    : "bg-danger-soft text-danger-soft-foreground",
                                isActive && "ring-2 ring-inset ring-accent",
                            )}
                        >
                            {testcase.passed ? (
                                <CheckIcon className="size-4" aria-hidden focusable="false" />
                            ) : (
                                <XIcon className="size-4" aria-hidden focusable="false" />
                            )}
                            {testcase.label}
                        </button>
                    )
                })}
            </div>

            {active.isSample ? (
                <IOExampleCard
                    rows={[
                        ...(active.input != null
                            ? [{ key: "in", label: labels.input, value: active.input }]
                            : []),
                        ...(active.expectedOutput != null
                            ? [{
                                key: "exp",
                                label: labels.expected,
                                value: active.expectedOutput,
                                tone: active.passed ? undefined : ("success" as const),
                            }]
                            : []),
                        ...(!active.passed && active.got != null
                            ? [{ key: "got", label: labels.got, value: active.got, tone: "danger" as const }]
                            : []),
                    ]}
                />
            ) : (
                <p className="text-xs text-muted">{labels.hidden}</p>
            )}
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"

/** Props for the {@link ActivityAvatar} block. */
export interface ActivityAvatarProps {
    /** Main avatar's username ΓÇö drives the image / initials fallback. */
    username: string
    /** Uploaded avatar URL (a generated default is used when missing). */
    avatar?: string | null
    /** Activity-type icon (phosphor `*Icon`) shown in the soft-accent badge. */
    icon: ReactNode
}

/**
 * Facebook-style feed avatar: a {@link UserAvatar} with a small activity-type icon
 * badge at the bottom-right. The badge is an OPAQUE soft-accent disc (a `bg-surface`
 * base under a `bg-accent-soft` tint so the avatar never bleeds through) with an
 * accent icon, and a surface ring cuts it cleanly from the avatar. The owning
 * feature decides whose avatar is the main one (e.g. the followed user on a
 * "followed" event). Pure/props-only; owns its look.
 *
 * @param props - {@link ActivityAvatarProps}
 */
export const ActivityAvatar = ({
    username,
    avatar,
    icon}: ActivityAvatarProps) => {
    return (
        <div className={"relative shrink-0"}>
            <UserAvatar
                className="size-9"
                username={username}
                avatar={avatar ?? undefined}
                seed={username}
            />
            <span
                aria-hidden
                className="absolute -bottom-1 -right-1 flex size-5 items-center justify-center rounded-full bg-surface ring-2 ring-surface"
            >
                <span className="flex size-full items-center justify-center rounded-full bg-accent-soft text-accent-soft-foreground [&_svg]:size-3">
                    {icon}
                </span>
            </span>
        </div>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import type { ReactNode } from "react"

/** Who authored a chat message. */
export type ChatRole = "user" | "assistant"

/** Props for the {@link ChatBubble} block. */
export interface ChatBubbleProps {
    /** Author of the message ΓÇö drives alignment + tint. */
    role: ChatRole
    /** Message content (text or a markdown render). */
    children: ReactNode
}

/**
 * A single chat message bubble: user messages align right with an accent tint,
 * assistant messages align left on the surface tint. Pure + props-only; owns its
 * look so chat features only compose it.
 *
 * @param props - {@link ChatBubbleProps}
 */
export const ChatBubble = ({ role, children}: ChatBubbleProps) => {
    const isUser = role === "user"
    return (
        <div className={cn("flex", isUser ? "justify-end" : "justify-start")}>
            <div
                className={cn(
                    "max-w-[85%] rounded-2xl px-3 py-2",
                    isUser ? "bg-accent-soft" : "bg-surface-secondary",
                )}
            >
                {children}
            </div>
        </div>
    )
}

"use client"

import React, { useEffect, useRef } from "react"
import { cn } from "@heroui/react"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { Composer } from "@/components/blocks/feed/Composer"
import type { ComposerProps } from "@/components/blocks/feed/Composer"

/** One message rendered by {@link ChatPanel}. */
export interface ChatPanelMessage {
    /** Stable id ΓÇö used as the React key. */
    id: string
    /** Author of the message ΓÇö maps to the {@link ChatBubble} alignment + tint. */
    role: "user" | "assistant"
    /** Message body (text or a markdown render), rendered inside the bubble. */
    content: React.ReactNode
    /**
     * Optional tool-result row rendered below the bubble, assistant-aligned ΓÇö e.g. a
     * {@link import("@/components/blocks/learn/ChatToolResult").ChatToolResult}. The
     * caller builds it; the panel only places it.
     */
    toolResult?: React.ReactNode
}

/**
 * Props for the {@link ChatPanel} block.
 *
 * A full chat surface: a scrollable message list, an optional typing indicator, an
 * empty-state slot, and a sticky-bottom {@link Composer}. Tier-3 presentational ΓÇö
 * all data + the composer wiring arrive via props; the only side-effect is an
 * auto-scroll-to-bottom effect on the list ref.
 */
export interface ChatPanelProps {
    /** The conversation, oldest first. Each entry renders one {@link ChatBubble}. */
    messages: Array<ChatPanelMessage>
    /** Props forwarded to the sticky-bottom {@link Composer} (controlled by the parent). */
    composer: ComposerProps
    /** When true, a three-dot typing indicator shows below the last message. */
    isTyping?: boolean
    /** Rendered centered in the list area when there are no messages. */
    emptyState?: React.ReactNode
}

/**
 * ChatPanel assembles the existing feed primitives into a complete chat surface:
 * a scrollable list of {@link ChatBubble}s (with optional tool-result rows
 * interleaved under assistant turns), an optional animated typing indicator, an
 * empty-state slot when the conversation is empty, and a sticky-bottom
 * {@link Composer} for the next message. The list auto-scrolls to the newest turn
 * whenever the messages or typing state change.
 *
 * Tier-3 presentational block: props-only, no store, no SWR. The parent owns the
 * message data and the composer's controlled draft.
 *
 * @param props - {@link ChatPanelProps}
 *
 * @example
 * <ChatPanel
 *   messages={turns}
 *   composer={{ value: draft, onChange: setDraft, onSubmit: send }}
 *   isTyping={isThinking}
 * />
 * @see Story: .storybook/stories/blocks/feed/ChatPanel/ChatPanel.stories
 */
export const ChatPanel = ({
    messages,
    composer,
    isTyping = false,
    emptyState}: ChatPanelProps) => {
    const listRef = useRef<HTMLDivElement>(null)

    // keep the newest turn in view as the conversation (or typing state) grows
    useEffect(() => {
        const element = listRef.current
        if (!element) {
            return
        }
        element.scrollTop = element.scrollHeight
    }, [messages, isTyping])

    const isEmpty = messages.length === 0

    return (
        <div
            className={cn("flex flex-col overflow-hidden rounded-3xl border border-default bg-surface",
                "h-[32rem]")}
        >
            {/* scrollable message list */}
            <div ref={listRef} className="flex-1 overflow-y-auto p-4">
                {isEmpty ? (
                    <div className="flex h-full items-center justify-center">
                        {emptyState}
                    </div>
                ) : (
                    <div className="flex flex-col gap-3">
                        {messages.map((message) => (
                            <div key={message.id} className="flex flex-col gap-2">
                                <ChatBubble role={message.role}>
                                    {message.content}
                                </ChatBubble>
                                {/* optional tool-result row, assistant-aligned under the bubble */}
                                {message.toolResult ? (
                                    <div className="flex justify-start">
                                        <div className="w-full max-w-[85%]">
                                            {message.toolResult}
                                        </div>
                                    </div>
                                ) : null}
                            </div>
                        ))}

                        {/* three-dot typing indicator on the assistant side */}
                        {isTyping ? (
                            <div className="flex justify-start">
                                <div className="flex items-center gap-1 rounded-2xl bg-surface-secondary px-3 py-3">
                                    {[0, 1, 2].map((dot) => (
                                        <span
                                            key={dot}
                                            className="size-1.5 animate-bounce rounded-full bg-muted"
                                            style={{ animationDelay: `${dot * 0.15}s` }}
                                        />
                                    ))}
                                </div>
                            </div>
                        ) : null}
                    </div>
                )}
            </div>

            {/* sticky-bottom composer */}
            <div className="border-t border-default p-3">
                <Composer {...composer} />
            </div>
        </div>
    )
}

"use client"

import React, {
    useEffect,
    useRef,
    useState,
} from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    SmileyIcon,
} from "@phosphor-icons/react"
import {
    AnimatePresence,
    motion,
} from "framer-motion"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** The six reactions + their emoji glyph, in display order. */
const REACTIONS: ReadonlyArray<{ type: ReactionType, emoji: string }> = [
    { type: ReactionType.Like, emoji: "≡ƒæì" },
    { type: ReactionType.Love, emoji: "Γ¥ñ∩╕Å" },
    { type: ReactionType.Haha, emoji: "≡ƒÿä" },
    { type: ReactionType.Wow, emoji: "≡ƒÿ«" },
    { type: ReactionType.Sad, emoji: "≡ƒÿó" },
    { type: ReactionType.Angry, emoji: "≡ƒÿá" },
]

/** Emoji glyph by reaction type. */
const EMOJI: Record<ReactionType, string> = REACTIONS.reduce(
    (acc, reaction) => {
        acc[reaction.type] = reaction.emoji
        return acc
    },
    {} as Record<ReactionType, string>,
)

/** Springy pop for the picker container; staggers its emoji children in. */
const PICKER_VARIANTS = {
    hidden: { opacity: 0, y: 8, scale: 0.8 },
    visible: {
        opacity: 1,
        y: 0,
        scale: 1,
        transition: { type: "spring", stiffness: 500, damping: 30, staggerChildren: 0.03 },
    },
    exit: { opacity: 0, y: 8, scale: 0.8, transition: { duration: 0.12 } },
} as const

/** Each emoji rises + scales in as the picker opens. */
const EMOJI_VARIANTS = {
    hidden: { opacity: 0, y: 6, scale: 0.5 },
    visible: { opacity: 1, y: 0, scale: 1 },
} as const

/** Props for the {@link ReactionBar} block. */
export interface ReactionBarProps {
    /** Total reactions on the target. */
    count: number
    /** The viewer's own reaction, or null. */
    myReaction: ReactionType | null
    /**
     * React handler ΓÇö pass the chosen emotion, or `null` to remove. **Omit to make
     * the bar READ-ONLY** (count display only, no picker) ΓÇö used when the viewer
     * may not react (e.g. their own activity, or anonymous).
     */
    onReact?: (type: ReactionType | null) => void
}

/**
 * Facebook-style reaction bar for a feed item: a react trigger (the viewer's
 * current emoji, or a neutral smiley) that pops a 6-emoji picker, beside the total
 * count. Tapping the same emotion removes it; tapping another switches. When
 * `onReact` is omitted the bar is READ-ONLY ΓÇö it shows just the count (+ the
 * viewer's emoji) and renders nothing when there are no reactions.
 *
 * Animation is pure `framer-motion` (no third-party emoji asset): the picker
 * springs up + staggers its emoji in, each emoji scales/lifts on hover and
 * squashes on tap, and the trigger emoji pops when the viewer's reaction changes.
 * Pure block: owns its look + the local picker-open state; the owning feature
 * supplies data + the react handler.
 *
 * @param props - {@link ReactionBarProps}
 * @see Story: .storybook/stories/blocks/feed/ReactionBar/ReactionBar.stories
 */
export const ReactionBar = ({
    count,
    myReaction,
    onReact}: ReactionBarProps) => {
    const [open, setOpen] = useState(false)
    const rootRef = useRef<HTMLDivElement>(null)

    // close the picker when clicking anywhere outside the bar
    useEffect(() => {
        if (!open) {
            return
        }
        const onPointerDown = (event: PointerEvent) => {
            if (rootRef.current && !rootRef.current.contains(event.target as Node)) {
                setOpen(false)
            }
        }
        document.addEventListener("pointerdown", onPointerDown)
        return () => document.removeEventListener("pointerdown", onPointerDown)
    }, [open])

    // close the picker on Escape, from anywhere within the bar
    useEffect(() => {
        if (!open) {
            return
        }
        const onKeyDown = (event: KeyboardEvent) => {
            if (event.key === "Escape") {
                setOpen(false)
            }
        }
        document.addEventListener("keydown", onKeyDown)
        return () => document.removeEventListener("keydown", onKeyDown)
    }, [open])

    // read-only: count + the viewer's emoji; nothing when there are no reactions
    if (!onReact) {
        if (count <= 0) {
            return null
        }
        return (
            <div className={"flex items-center gap-1"}>
                {myReaction ? <span aria-hidden>{EMOJI[myReaction]}</span> : null}
                <Typography type="body-xs" color="muted">{count}</Typography>
            </div>
        )
    }

    /** Pick (or toggle off) an emotion, then close the picker. */
    const pick = (type: ReactionType) => {
        onReact(myReaction === type ? null : type)
        setOpen(false)
    }

    return (
        <div
            ref={rootRef}
            className={"relative flex items-center gap-2"}
        >
            <button
                type="button"
                aria-label="React"
                aria-expanded={open}
                onClick={() => setOpen((previous) => !previous)}
                className="flex items-center gap-1 rounded-full px-2 py-0 text-muted transition-colors hover:bg-default/40 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
            >
                <AnimatePresence mode="popLayout" initial={false}>
                    {myReaction ? (
                        <motion.span
                            key={myReaction}
                            aria-hidden
                            className="text-sm leading-none"
                            initial={{ scale: 0, rotate: -30 }}
                            animate={{ scale: 1, rotate: 0 }}
                            exit={{ scale: 0, rotate: 30 }}
                            transition={{ type: "spring", stiffness: 600, damping: 20 }}
                        >
                            {EMOJI[myReaction]}
                        </motion.span>
                    ) : (
                        <motion.span
                            key="placeholder"
                            initial={{ scale: 0.6 }}
                            animate={{ scale: 1 }}
                            className="flex"
                        >
                            <SmileyIcon aria-hidden focusable="false" className="size-4" />
                        </motion.span>
                    )}
                </AnimatePresence>
                {count > 0 ? (
                    <Typography type="body-xs" className={cn(myReaction ? "text-accent-soft-foreground" : "text-muted")}>
                        {count}
                    </Typography>
                ) : null}
            </button>

            <AnimatePresence>
                {open ? (
                    <motion.div
                        variants={PICKER_VARIANTS}
                        initial="hidden"
                        animate="visible"
                        exit="exit"
                        style={{ transformOrigin: "bottom left" }}
                        className="absolute bottom-full left-0 z-10 mb-1 flex items-center gap-1 rounded-full bg-surface p-1 ring-1 ring-separator"
                    >
                        {REACTIONS.map((reaction) => (
                            <motion.button
                                key={reaction.type}
                                type="button"
                                aria-label={reaction.type}
                                variants={EMOJI_VARIANTS}
                                whileHover={{ scale: 1.4, y: -4 }}
                                whileTap={{ scale: 0.85 }}
                                transition={{ type: "spring", stiffness: 500, damping: 18 }}
                                onClick={() => pick(reaction.type)}
                                className={cn(
                                    "flex size-7 items-center justify-center rounded-full text-base leading-none focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent",
                                    myReaction === reaction.type && "bg-accent-soft",
                                )}
                            >
                                <span aria-hidden>{reaction.emoji}</span>
                            </motion.button>
                        ))}
                    </motion.div>
                ) : null}
            </AnimatePresence>
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/** Props for {@link Timeline}. */
export interface TimelineProps {
    /**
     * The row elements to render inside the timeline. Each child is expected to
     * be a self-contained row block (e.g. {@link FeedItem}) that describes one
     * activity or attempt. The Timeline only provides the vertical connector and
     * spacing ΓÇö row content and layout are entirely the caller's responsibility.
     */
    children: ReactNode
}

/**
 * Vertical timeline wrapper that stacks activity or attempt row blocks beside a
 * continuous left connector line. The line is drawn with `border-l
 * border-separator` on the container; children are indented with `pl-4` so the
 * line runs to their left.
 *
 * Purely presentational tier-3 block: holds no state, performs no data access,
 * and applies no visual frame. Pass pre-built row blocks (e.g. FeedItem) as
 * `children`.
 *
 * @param props - {@link TimelineProps}
 * @see Story: .storybook/stories/blocks/feed/Timeline/Timeline.stories
 */
export const Timeline = ({ children}: TimelineProps) => {
    return (
        <div
            className={cn("relative flex flex-col gap-3",
                "border-l border-separator",
                "pl-4")}
        >
            {children}
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import dynamic from "next/dynamic"
import { Chip, Skeleton } from "@heroui/react"
import { useTranslations } from "next-intl"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import type { HealthByName } from "@/hooks/useSystemHealthPoll"
import { ARCHITECTURE_MODULE_MAP } from "@/modules/utils/architecture-modules"
import { buildLiveScene } from "@/modules/utils/architecture-live-scene"
import { buildFutureScene } from "@/modules/utils/architecture-future-scene"

/** The R3F canvas is heavy + client-only ΓÇö lazy so it never ships in the RSC
 *  bundle and never mounts during SSR. */
const ArchitectureScene = dynamic(
    () => import("@/components/blocks/marketing/ArchitectureScene").then((mod) => mod.ArchitectureScene),
    {
        ssr: false,
        loading: () => <Skeleton className="h-[440px] w-full rounded-3xl @app-sm:h-[560px]" />,
    },
)

/** Which era the map shows: today's live system, or the future roadmap. */
export type ArchitectureEra = "present" | "future"

/** Props for {@link ArchitectureMap}. */
export interface ArchitectureMapProps {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Currently selected node id ΓÇö highlighted with a ring on the map. */
    selectedId: string
    /** Click-to-select a node ΓÇö kept in sync with the rail via `?node=`. */
    onSelectNode: (id: string) => void
}

/**
 * The live 3D architecture ATLAS ΓÇö one flat isometric board, no pods, no drill.
 * Two eras via a single toggle:
 *
 *  - **Present** (default): the live atlas ΓÇö all 17 infra/external components
 *    (live status dot) PLUS the 10 feature modules the Core API splits into
 *    (neutral, no dot ΓÇö no health probe exists for them). Selecting a module
 *    brightens the infra it runs on ({@link buildLiveScene}); selecting infra
 *    highlights it. Everything on one grid, one tile per node.
 *  - **Future**: the microservices roadmap (Coming soon ΓÇö no live status).
 *
 * The `?node=` selection is shared with the rail + dissection panel. Every scene
 * builder is a pure data function fed i18n'd labels here.
 *
 * @param props - {@link ArchitectureMapProps}
 */
export const ArchitectureMap = ({ healthByName, selectedId, onSelectNode}: ArchitectureMapProps) => {
    const t = useTranslations("architecture")

    const [era, setEra] = React.useState<ArchitectureEra>("present")

    // stable per-scene i18n label bags (memoised on t so scene builders stay pure)
    const flatLabels = useMemo(
        () => ({
            checking: t("status.checking"),
            unknown: t("status.unknown"),
            degraded: t("status.degraded"),
            down: t("status.down"),
            client: t("map.client"),
            clientSub: t("map.clientSub"),
            gateway: t("map.gateway"),
            gatewaySub: t("map.gatewaySub"),
            moduleName: (id: string) => t(`module.${id}.name`),
            moduleSub: (id: string) => {
                const value = t(`module.${id}.sub`)
                return value || undefined
            },
        }),
        [t],
    )
    const futureLabels = useMemo(
        () => ({
            bus: t("future.bus"),
            busSub: t("future.busSub"),
            service: (key: string) => t(`future.${key}`),
        }),
        [t],
    )

    const data = useMemo(
        () => (era === "future" ? buildFutureScene(futureLabels) : buildLiveScene(healthByName, flatLabels, selectedId)),
        [era, healthByName, flatLabels, futureLabels, selectedId],
    )

    // nothing is selectable in the future (roadmap) scene
    const onSelect = (id: string) => {
        if (era === "future") return
        onSelectNode(id)
    }

    const highlightId = era === "future" ? undefined : selectedId

    const caption = era === "future"
        ? t("future.caption")
        : ARCHITECTURE_MODULE_MAP[selectedId]
            ? t("map.moduleHint")
            : t("map.atlasHint")

    return (
        <div className={"flex flex-col gap-3"}>
            {/* era switch (present Γçä future) ΓÇö no pod/layout toggle anymore */}
            <div data-principle="content-row" className="flex flex-wrap items-center justify-between gap-3">
                <TabsCard
                    variant="primary"
                    className="w-full max-w-xs"
                    leftTabs={{
                        selectedKey: era,
                        ariaLabel: t("view.eraAria"),
                        onSelectionChange: (key) => setEra(String(key) as typeof era),
                        items: [
                            { key: "present", label: t("view.present") },
                            { key: "future", label: t("view.future") },
                        ],
                    }}
                />
                {era === "future" ? (
                    <Chip size="sm" className="bg-accent-soft text-accent-soft-foreground">
                        <Chip.Label>{t("future.comingSoon")}</Chip.Label>
                    </Chip>
                ) : null}
            </div>

            <ArchitectureScene
                data={data}
                selectedId={highlightId}
                onSelectNode={onSelect}
                caption={caption}
            />
        </div>
    )
}

"use client"

import React from "react"
import { ScrollShadow, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ARCHITECTURE_COMPONENTS } from "@/modules/utils/architecture-catalog"
import { ARCHITECTURE_MODULES } from "@/modules/utils/architecture-modules"
import type { HealthByName } from "@/hooks/useSystemHealthPoll"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "@/modules/utils/architecture-status-visual"
import { StackH } from "@/components/frames/Stack"

/** Props for {@link ArchitectureMobileNav}. */
export interface ArchitectureMobileNavProps {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Selected node id, mirrored to `?node=`. */
    selectedId: string
    /** Selects a node ΓÇö shares state with {@link import("..").ArchitectureRail}. */
    onSelect: (id: string) => void
}

/** One selectable chip: icon + name + status dot. */
const NodeChip = ({
    name,
    icon: Icon,
    healthByName,
    selected,
    onSelect,
}: NodeChipProps) => {
    const state = resolveArchitectureStatus(name, healthByName)
    const visual = getArchitectureStatusVisual(state)
    return (
        <button
            type="button"
            aria-pressed={selected}
            onClick={onSelect}
            className={cn(
                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                selected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
            )}
        >
            <Icon aria-hidden className="size-4 shrink-0" />
            <Typography type="body-sm" className={selected ? "text-accent-soft-foreground" : undefined}>{name}</Typography>
            <span className={cn("size-2 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
        </button>
    )
}

/** One module chip: icon + name, NO status dot (modules have no health probe). */
const ModuleChip = ({
    id,
    icon: Icon,
    selected,
    onSelect,
}: ModuleChipProps) => {
    const t = useTranslations("architecture")
    return (
        <button
            type="button"
            aria-pressed={selected}
            onClick={onSelect}
            className={cn(
                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                selected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
            )}
        >
            <Icon aria-hidden className="size-4 shrink-0" />
            <Typography type="body-sm" className={selected ? "text-accent-soft-foreground" : undefined}>{t(`module.${id}.name`)}</Typography>
        </button>
    )
}

/**
 * Mobile counterpart of {@link import("..").ArchitectureRail}: below `lg` the
 * docs-style rail hides, so the component list folds into two horizontally
 * scrollable chip rows (own system, then external dependencies) above the map
 * ΓÇö the master-detail mobile pattern (mirrors `PracticeMobileNav`). Reads/
 * writes the same `?node=` state as the rail, so the two stay in lockstep.
 *
 * @param props - {@link ArchitectureMobileNavProps}
 */
export const ArchitectureMobileNav = ({ healthByName, selectedId, onSelect}: ArchitectureMobileNavProps) => {
    const t = useTranslations("architecture")
    const ownComponents = ARCHITECTURE_COMPONENTS.filter((c) => c.group === "own")
    const externalComponents = ARCHITECTURE_COMPONENTS.filter((c) => c.group === "external")

    return (
        <div className={"flex flex-col gap-3 @app-lg:hidden"}>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.ownGroup")}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={ownComponents.map((component) => (
                            () => (
                                <NodeChip
                                    name={component.name}
                                    icon={component.icon}
                                    healthByName={healthByName}
                                    selected={selectedId === component.name}
                                    onSelect={() => onSelect(component.name)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.externalGroup")}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={externalComponents.map((component) => (
                            () => (
                                <NodeChip
                                    name={component.name}
                                    icon={component.icon}
                                    healthByName={healthByName}
                                    selected={selectedId === component.name}
                                    onSelect={() => onSelect(component.name)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
            <div data-principle="sibling-stack" className="flex flex-col gap-2">
                <Typography type="body-xs" color="muted">{t("rail.moduleGroup", { count: ARCHITECTURE_MODULES.length })}</Typography>
                <ScrollShadow orientation="horizontal" hideScrollBar className="overflow-x-auto pb-1">
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={ARCHITECTURE_MODULES.map((module) => (
                            () => (
                                <ModuleChip
                                    id={module.id}
                                    icon={module.icon}
                                    selected={selectedId === module.id}
                                    onSelect={() => onSelect(module.id)}
                                />
                            )
                        ))}
                    />
                </ScrollShadow>
            </div>
        </div>
    )
}

type NodeChipProps = {
    name: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    healthByName: HealthByName | null
    selected: boolean
    onSelect: () => void
}
type ModuleChipProps = {
    id: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    selected: boolean
    onSelect: () => void
}

"use client"

import React, { useMemo } from "react"
import { Label, ListBox, ScrollShadow, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ARCHITECTURE_COMPONENTS } from "@/modules/utils/architecture-catalog"
import { ARCHITECTURE_MODULES } from "@/modules/utils/architecture-modules"
import type { HealthByName } from "@/hooks/useSystemHealthPoll"
import { MetricsInline } from "../MetricsInline"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "@/modules/utils/architecture-status-visual"

/** Props for {@link ArchitectureRail}. */
export interface ArchitectureRailProps {
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
    /** Selected node id, mirrored to `?node=`. */
    selectedId: string
    /** Selects a node (rail row, map click, or mobile chip all call this). */
    onSelect: (id: string) => void
}

/** One rail row: icon + name/tagline + a live status dot WITH a text label ΓÇö
 *  never color-only (a11y: dot + text, ΓëÑ3:1 contrast). Shared by both the
 *  "own" and "external" groups below. */
const ComponentRow = ({
    name,
    icon: Icon,
    healthByName,
}: ComponentRowProps) => {
    const t = useTranslations("architecture")
    const state = resolveArchitectureStatus(name, healthByName)
    const visual = getArchitectureStatusVisual(state)
    const metrics = healthByName?.[name]?.metrics
    return (
        <span data-principle="identity" className="flex w-full min-w-0 items-center gap-2">
            <Icon aria-hidden className="size-4 shrink-0 text-muted" />
            <span className="flex min-w-0 flex-1 flex-col">
                <Typography type="body-sm" weight="medium" className="min-w-0 truncate">
                    {name}
                </Typography>
                <Typography type="body-xs" color="muted" className="min-w-0 truncate">
                    {t(`rail.tagline.${name}`)}
                </Typography>
                {/* only components with a local Docker container carry metrics ΓÇö a
                    row with none (judge0, ollama, mail, aiBalancer, external SaaS)
                    simply stays 2 lines, no fake placeholder line */}
                <MetricsInline metrics={metrics} className="text-xs text-muted" />
            </span>
            <span className={cn("flex shrink-0 items-center gap-2 rounded-full px-2 py-0", visual.chipClassName)}>
                <span className={cn("size-1.5 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
                <Typography type="body-xs" className="whitespace-nowrap">
                    {t(`status.${state}`)}
                </Typography>
            </span>
        </span>
    )
}

/** One module rail row: icon + name + one-line sub. NO status dot ΓÇö modules
 *  have no health probe (honesty), so a green/gray dot would be fabricated. */
const ModuleRow = ({
    id,
    icon: Icon,
}: ModuleRowProps) => {
    const t = useTranslations("architecture")
    return (
        <span data-principle="identity" className="flex w-full min-w-0 items-center gap-2">
            <Icon aria-hidden className="size-4 shrink-0 text-muted" />
            <span className="flex min-w-0 flex-1 flex-col">
                <Typography type="body-sm" weight="medium" className="min-w-0 truncate">
                    {t(`module.${id}.name`)}
                </Typography>
                <Typography type="body-xs" color="muted" className="min-w-0 truncate">
                    {t(`module.${id}.sub`)}
                </Typography>
            </span>
        </span>
    )
}

/**
 * Desktop LEFT RAIL ΓÇö the "docs-style" sidebar (pinned header + scroll region,
 * full rail height) listing every probed component, GROUPED into StarCi's own
 * system vs the external SaaS it depends on. Selecting a row drives the shared
 * `?node=` state (rail Γçä map Γçä dissection panel). Placed in the rail column by
 * the page shell; reads/writes URL state via the `onSelect` callback + the
 * `selectedId` prop (owned by the parent so the mobile chip row stays in sync
 * too).
 *
 * @param props - {@link ArchitectureRailProps}
 */
export const ArchitectureRail = ({ healthByName, selectedId, onSelect }: ArchitectureRailProps) => {
    const t = useTranslations("architecture")

    const ownComponents = useMemo(() => ARCHITECTURE_COMPONENTS.filter((c) => c.group === "own"), [])
    const externalComponents = useMemo(() => ARCHITECTURE_COMPONENTS.filter((c) => c.group === "external"), [])

    const onSelectionChange = (keys: Set<React.Key> | "all") => {
        if (keys === "all") return
        const key = [...keys][0]
        if (typeof key === "string") onSelect(key)
    }

    return (
        <div className="relative flex min-h-0 min-w-0 flex-col gap-3 p-6">
            <ScrollShadow hideScrollBar className="-mx-1 min-h-0 min-w-0 flex-1 overflow-y-auto px-1" data-principle="control-pad">
                <div data-principle="card-caption" className="flex flex-col gap-3">
                    <div data-principle="sibling-stack" className="flex flex-col gap-2">
                        <Label className="px-1 text-xs text-muted" data-principle="control-pad">{t("rail.ownGroup")}</Label>
                        <ListBox
                            aria-label={t("rail.ownGroup")}
                            selectionMode="single"
                            selectedKeys={ownComponents.some((c) => c.name === selectedId) ? [selectedId] : []}
                            onSelectionChange={onSelectionChange}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {ownComponents.map((component) => (
                                <ListBox.Item
                                    key={component.name}
                                    id={component.name}
                                    textValue={component.name}
                                    className="cursor-pointer rounded-2xl px-3 py-2 data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft" data-principle="control-pad"
                                >
                                    <ComponentRow name={component.name} icon={component.icon} healthByName={healthByName} />
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    </div>

                    <div data-principle="sibling-stack" className="flex flex-col gap-2">
                        <Label className="px-1 text-xs text-muted" data-principle="control-pad">{t("rail.externalGroup")}</Label>
                        <ListBox
                            aria-label={t("rail.externalGroup")}
                            selectionMode="single"
                            selectedKeys={externalComponents.some((c) => c.name === selectedId) ? [selectedId] : []}
                            onSelectionChange={onSelectionChange}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {externalComponents.map((component) => (
                                <ListBox.Item
                                    key={component.name}
                                    id={component.name}
                                    textValue={component.name}
                                    className="cursor-pointer rounded-2xl px-3 py-2 data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft" data-principle="control-pad"
                                >
                                    <ComponentRow name={component.name} icon={component.icon} healthByName={healthByName} />
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    </div>

                    <div data-principle="sibling-stack" className="flex flex-col gap-2">
                        <Label className="px-1 text-xs text-muted" data-principle="control-pad">
                            {t("rail.moduleGroup", { count: ARCHITECTURE_MODULES.length })}
                        </Label>
                        <ListBox
                            aria-label={t("rail.moduleGroup", { count: ARCHITECTURE_MODULES.length })}
                            selectionMode="single"
                            selectedKeys={ARCHITECTURE_MODULES.some((m) => m.id === selectedId) ? [selectedId] : []}
                            onSelectionChange={onSelectionChange}
                            className="gap-1 p-0" data-principle="title-subtitle"
                        >
                            {ARCHITECTURE_MODULES.map((module) => (
                                <ListBox.Item
                                    key={module.id}
                                    id={module.id}
                                    textValue={module.id}
                                    className="cursor-pointer rounded-2xl px-3 py-2 data-[hovered=true]:bg-default-100 data-[selected=true]:bg-accent-soft" data-principle="control-pad"
                                >
                                    <ModuleRow id={module.id} icon={module.icon} />
                                </ListBox.Item>
                            ))}
                        </ListBox>
                    </div>
                </div>
            </ScrollShadow>
        </div>
    )
}

type ComponentRowProps = {
    name: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
    healthByName: HealthByName | null
}
type ModuleRowProps = {
    id: string
    icon: React.ComponentType<{ className?: string; "aria-hidden"?: boolean }>
}

import React from "react"
import { cn } from "@heroui/react"
import { ArrowsDownUpIcon, CpuIcon, MemoryIcon } from "@phosphor-icons/react"
import type { ComponentMetrics } from "@/modules/api/graphql/queries/types/system-health-status"
import { formatBytesPerSecond, formatCpuPercent, formatMemory } from "@/modules/utils/architecture-metrics"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link MetricsInline}. */
export interface MetricsInlineProps extends WithClassNames<undefined> {
    /** Live resource metrics for this component, or `null`/`undefined` when
     *  there's no local container to measure (or no sample yet) ΓÇö renders
     *  nothing rather than a fake placeholder. */
    metrics: ComponentMetrics | null | undefined
}

/**
 * A compact CPU / memory / network readout for one component, shared by
 * {@link import("../ArchitectureRail").ArchitectureRail} (rail row) and
 * {@link import("../NodeDissectionPanel").NodeDissectionPanel} (detail panel) ΓÇö
 * same "flex-wrap of small icon+text chips" treatment `panel.latency` already
 * uses. Every field is independently gated on being non-null: a component
 * with only, say, `cpuPercent` known shows just that one chip, never a `0`/
 * "N/A" filler for the others. Renders nothing at all when every field is null.
 *
 * @param props - {@link MetricsInlineProps}
 */
export const MetricsInline = ({ metrics, className }: MetricsInlineProps) => {
    const cpu = formatCpuPercent(metrics?.cpuPercent)
    const memory = formatMemory(metrics?.memoryUsedBytes, metrics?.memoryLimitBytes)
    const network = metrics
        ? [formatBytesPerSecond(metrics.networkRxBytesPerSec), formatBytesPerSecond(metrics.networkTxBytesPerSec)]
        : [null, null]
    const [rx, tx] = network

    if (cpu == null && memory == null && rx == null && tx == null) return null

    return (
        <span className={cn("flex flex-wrap items-center gap-x-3 gap-y-1", className)}>
            {cpu != null ? (
                <span data-principle="icon-text" className="inline-flex items-center gap-1 tabular-nums">
                    <CpuIcon aria-hidden focusable="false" className="size-3 shrink-0" />
                    {cpu}
                </span>
            ) : null}
            {memory != null ? (
                <span data-principle="icon-text" className="inline-flex items-center gap-1 tabular-nums">
                    <MemoryIcon aria-hidden focusable="false" className="size-3 shrink-0" />
                    {memory}
                </span>
            ) : null}
            {rx != null || tx != null ? (
                <span data-principle="icon-text" className="inline-flex items-center gap-1 tabular-nums">
                    <ArrowsDownUpIcon aria-hidden focusable="false" className="size-3 shrink-0" />
                    {rx != null ? `Γåô ${rx}` : null}
                    {rx != null && tx != null ? " " : null}
                    {tx != null ? `Γåæ ${tx}` : null}
                </span>
            ) : null}
        </span>
    )
}

"use client"

import React, { useMemo } from "react"
import { Card, Link, Typography, cn } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { ArrowUpRightIcon, BookOpenTextIcon } from "@phosphor-icons/react"
import { Callout } from "@/components/composites/feedback/Callout"
import { SimpleEmptyState } from "@/components/blocks/feedback/SimpleEmptyState"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { pathConfig } from "@/resources/path"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { ARCHITECTURE_COMPONENT_MAP } from "@/modules/utils/architecture-catalog"
import { ARCHITECTURE_MODULE_MAP } from "@/modules/utils/architecture-modules"
import type { HealthByName } from "@/hooks/useSystemHealthPoll"
import { MetricsInline } from "../MetricsInline"
import { getArchitectureStatusVisual, resolveArchitectureStatus } from "@/modules/utils/architecture-status-visual"

/** Props for {@link NodeDissectionPanel}. */
export interface NodeDissectionPanelProps {
    /** Selected component name (must exist in the catalog). */
    nodeId: string
    /** Live health keyed by component name, or `null` before the first probe resolves. */
    healthByName: HealthByName | null
}

/**
 * The "dissection" panel for the currently selected node: identity (icon +
 * name + role), live status (dot + text + latency + relative freshness), a
 * short "why this matters" note, and ΓÇö when the component has one ΓÇö a link to
 * its StarCi engineering-blog deep-dive. Public-safe only: no secrets, no
 * connection strings, just role + live traffic-light + a public failure
 * message when down.
 *
 * @param props - {@link NodeDissectionPanelProps}
 */
export const NodeDissectionPanel = ({ nodeId, healthByName}: NodeDissectionPanelProps) => {
    const t = useTranslations("architecture")
    const tRoot = useTranslations()
    const locale = useLocale()
    const component = ARCHITECTURE_COMPONENT_MAP[nodeId]

    const state = resolveArchitectureStatus(nodeId, healthByName)
    const visual = getArchitectureStatusVisual(state)
    const health = healthByName?.[nodeId] ?? null

    const checkedAgo = useMemo(
        () => (health ? getTimeAgoLabel(getTimeAgoMessage(health.checkedAt), tRoot) : null),
        [health, tRoot],
    )

    // feature module (Core API split) ΓÇö no health probe exists, so no status /
    // metrics / blog: identity + role + the real infra it runs on (grounded in
    // `usesInfra`), which is exactly what makes the "Core ΓåÆ modules" reading legible.
    const module = ARCHITECTURE_MODULE_MAP[nodeId]
    if (module) {
        const ModuleIcon = module.icon
        const infraNames = module.usesInfra.map((id) => ARCHITECTURE_COMPONENT_MAP[id]?.name ?? id)
        return (
            <Card className={""}>
                <Box principle="page-pad" className="p-6"
                    explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                    <StackV gap={5} principle="group-boundary"
                        explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => (
                                <div data-principle="content-row" className="flex min-w-0 items-center gap-3">
                                    <IconTile icon={<ModuleIcon aria-hidden />} tone="neutral" size="sm" />
                                    <div className="flex min-w-0 flex-col">
                                        <Typography type="h4" weight="semibold" className="min-w-0 truncate">
                                            {t(`module.${module.id}.name`)}
                                        </Typography>
                                        <Typography type="body-sm" color="muted">
                                            {t(`module.${module.id}.sub`)}
                                        </Typography>
                                    </div>
                                </div>
                            ),
                            () => (
                                <div data-principle="sibling-stack" className="flex flex-col gap-2 border-t border-default pt-3">
                                    <Typography type="body-sm" weight="medium">{t("panel.whyHeading")}</Typography>
                                    <Typography type="body-sm" color="muted">{t(`module.${module.id}.role`)}</Typography>
                                </div>
                            ),
                            () => (
                                <div data-principle="sibling-stack" className="flex flex-col gap-2 border-t border-default pt-3">
                                    <Typography type="body-sm" weight="medium">{t("panel.runsOn")}</Typography>
                                    <div data-principle="chip-row" className="flex flex-wrap gap-2">
                                        {infraNames.map((name) => (
                                            <span key={name} data-principle="control-pad" className="rounded-full bg-default px-2 py-1 font-mono text-xs text-muted">
                                                {name}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            ),
                        ]} />
                </Box>
            </Card>
        )
    }

    if (!component) {
        return (
            <Card className={""}>
                <Box principle="page-pad" className="p-6"
                    explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                    <SimpleEmptyState>{t("panel.notFound")}</SimpleEmptyState>
                </Box>
            </Card>
        )
    }

    const Icon = component.icon
    const blogHref = component.blogSlug
        ? `${pathConfig().locale(locale).blog().build()}/${component.blogSlug}`
        : null

    return (
        <Card className={""}>
            <Box principle="page-pad" className="p-6"
                explain="Page chrome inset ΓÇö not card-padding, because this pads the whole page rather than a nested card surface.">
                <StackV gap={5} principle="group-boundary"
                    explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                    items={[
                        () => (
                            <div data-principle="content-row" className="flex items-start justify-between gap-3">
                                <div data-principle="content-row" className="flex min-w-0 items-center gap-3">
                                    <IconTile icon={<Icon aria-hidden />} tone="neutral" size="sm" />
                                    <div className="flex min-w-0 flex-col">
                                        <Typography type="h4" weight="semibold" className="min-w-0 truncate font-mono">
                                            {component.name}
                                        </Typography>
                                        <Typography type="body-sm" color="muted">
                                            {t(`role.${component.name}`)}
                                        </Typography>
                                    </div>
                                </div>
                                <span className={cn("flex shrink-0 items-center gap-2 rounded-full px-2 py-1", visual.chipClassName)}>
                                    <span className={cn("size-2 shrink-0 rounded-full", visual.dotClassName, visual.pulse && "animate-pulse")} aria-hidden />
                                    <Typography type="body-xs" weight="medium" className="whitespace-nowrap">
                                        {t(`status.${state}`)}
                                    </Typography>
                                </span>
                            </div>
                        ),
                        () => (
                            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted">
                                <span className="tabular-nums">
                                    {health?.latencyMs == null ? "ΓÇö" : t("panel.latency", { ms: health.latencyMs })}
                                </span>
                                {checkedAgo ? <span>{t("panel.checked", { ago: checkedAgo })}</span> : null}
                                <MetricsInline metrics={health?.metrics} />
                            </div>
                        ),
                        ...(health?.message ? [
                            () => {
                                const message = health.message!
                                return <Callout status="danger" title={message} />
                            },
                        ] : []),
                        () => (
                            <div data-principle="sibling-stack" className="flex flex-col gap-2 border-t border-default pt-3">
                                <Typography type="body-sm" weight="medium">{t("panel.whyHeading")}</Typography>
                                <Typography type="body-sm" color="muted">{t(`why.${component.name}`)}</Typography>
                            </div>
                        ),
                        ...(blogHref ? [
                            () => (
                                <Link href={blogHref} data-principle="flex-action" className="group inline-flex items-center gap-2 text-accent-soft-foreground">
                                    <BookOpenTextIcon aria-hidden focusable="false" className="size-4" />
                                    {t("panel.deepDive")}
                                    <ArrowUpRightIcon
                                        aria-hidden
                                        focusable="false"
                                        className="size-4 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5"
                                    />
                                </Link>
                            ),
                        ] : []),
                    ]} />
            </Box>
        </Card>
    )
}

"use client"

import React from "react"
import { Alert, Button, Link, Skeleton, Typography } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ArrowRightIcon, ArrowUpRightIcon } from "@phosphor-icons/react"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { pathConfig } from "@/resources/path"
import { ArchitectureRail } from "./ArchitectureRail"
import { ArchitectureMobileNav } from "./ArchitectureRail/ArchitectureMobileNav"
import { ArchitectureMap } from "./ArchitectureMap"
import { NodeDissectionPanel } from "./NodeDissectionPanel"
import { CurlTester } from "./CurlTester"
import { useArchitectureNode } from "@/hooks/useArchitectureNode"
import { useSystemHealthPoll } from "@/hooks/useSystemHealthPoll"

/** Public GitHub repo backing this live atlas ΓÇö the "don't trust me, go read it" link. */
const BACKEND_REPO_URL = "https://github.com/starci-lab/starci-academy-backend"

/**
 * `/architecture` ΓÇö the public "System Atlas": a live, interactive tour of
 * StarCi's real backend. Laid out docs-style like {@link import("../practice").Practice}:
 * a persistent left {@link ArchitectureRail} (every probed component, grouped
 * "StarCi's own system" vs "external dependencies", each row carrying a live
 * status dot) beside a padded work pane ΓÇö the 3D {@link ArchitectureMap}, the
 * selected node's {@link NodeDissectionPanel}, and a {@link CurlTester} anyone
 * can run to prove the platform is really answering. Below `lg` the rail folds
 * into {@link ArchitectureMobileNav} chip rows.
 *
 * Honesty rule (see `system-map-conceptual-nodes-not-containers`): every dot on
 * this page traces to a REAL probe from the public `systemHealthStatus` query ΓÇö
 * before the first sweep resolves every node reads "checkingΓÇª" (gray/pulse),
 * never a synthesized green. The map keeps rendering with `healthByName: null`
 * during that window (its own nodes render "checking"), so only a genuine fetch
 * failure (no cache to fall back to) swaps in the error state below.
 */
export const ArchitecturePage = () => {
    const t = useTranslations("architecture")
    const tGlobal = useTranslations()
    const router = useRouter()
    const locale = useLocale()
    const { node, setNode } = useArchitectureNode()
    const { healthByName, isLoading, error, refresh } = useSystemHealthPoll()

    const onOpenCourses = () => router.push(pathConfig().locale(locale).course().build())

    return (
        // single column on mobile/tablet; rail + content side-by-side from lg up
        <div className="flex w-full flex-col items-start @app-lg:flex-row">
            {/* docs-style left rail ΓÇö sticks under the navbar, viewport-tall, drag-resizable */}
            <ResizableRail
                className="hidden shrink-0 @app-lg:sticky @app-lg:top-16 @app-lg:flex @app-lg:h-[calc(100dvh-4rem)] @app-lg:flex-col @app-lg:self-start"
                storageKey="starci.architecture.rail.width"
                defaultWidth={300}
                minWidth={256}
                maxWidth={420}
                ariaLabel={t("rail.ariaLabel")}
            >
                <FillAvailable
                    at="lg"
                    body={() => (
                        <ArchitectureRail
                            healthByName={healthByName}
                            selectedId={node}
                            onSelect={setNode}
                        />
                    )}
                />
            </ResizableRail>

            {/* content column ΓÇö owns the canonical p-6 reading padding */}
            <div data-principle="page-pad" className="min-h-0 min-w-0 flex-1 p-6">
                <div data-principle="center-measure" className="mx-auto flex max-w-5xl flex-col gap-10">
                    <PageHeader
                        breadcrumb={(
                            <ResponsiveBreadcrumb
                                items={[
                                    {
                                        key: "home",
                                        label: tGlobal("nav.home"),
                                        onPress: () => router.push(pathConfig().locale().build()),
                                    },
                                    {
                                        key: "current",
                                        label: t("title"),
                                    },
                                ]}
                            />
                        )}
                        title={t("title")}
                        description={t("subtitle")}
                        actions={(
                            <div data-principle="flex-action" className="flex flex-wrap items-center gap-2">
                                <Link href={BACKEND_REPO_URL} target="_blank" rel="noopener noreferrer">
                                    <Button variant="tertiary" size="sm">
                                        {t("header.viewSource")}
                                        <ArrowUpRightIcon className="size-4" aria-hidden />
                                    </Button>
                                </Link>
                                <Button variant="primary" size="sm" onPress={onOpenCourses}>
                                    {t("header.viewCourse")}
                                    <ArrowRightIcon className="size-4" aria-hidden />
                                </Button>
                            </div>
                        )}
                    />

                    <div data-principle="block-boundary" className="flex flex-col gap-6">
                        {/* mobile: component chips (the rail is desktop-only) */}
                        <ArchitectureMobileNav healthByName={healthByName} selectedId={node} onSelect={setNode} />

                        {/* the topology map ALWAYS renders ΓÇö it's static structure, valuable
                            even when the health API is unreachable. Only the very first load
                            (no data yet, not failed) shows a skeleton; a genuine fetch failure
                            surfaces as a small inline note above the map (nodes fall back to the
                            honest "checkingΓÇª"/"unknown" tones), never hides the whole diagram. */}
                        {isLoading && !healthByName && !error ? (
                            <Skeleton className="h-[440px] w-full rounded-3xl @app-sm:h-[560px]" />
                        ) : (
                            <>
                                {error && !healthByName ? (
                                    <Alert status="default">
                                        <Alert.Indicator />
                                        <Alert.Content>
                                            <Alert.Title>{t("map.errorDescription")}</Alert.Title>
                                        </Alert.Content>
                                        <Button variant="tertiary" size="sm" onPress={refresh}>{t("map.retry")}</Button>
                                    </Alert>
                                ) : null}
                                <ArchitectureMap
                                    healthByName={healthByName}
                                    selectedId={node}
                                    onSelectNode={setNode}
                                />
                            </>
                        )}

                        <NodeDissectionPanel nodeId={node} healthByName={healthByName} />

                        <SurfaceCard label={t("curl.heading")} body={CurlTester} />

                        {/* course-CTA band ΓÇö closes the loop: this real, live system is
                            exactly what the courses teach you to build ΓåÆ go learn to build it */}
                        <div data-principle="page-pad" className="rounded-3xl bg-accent-soft p-6">
                            <div data-principle="content-row" className="flex flex-col items-start gap-3 @app-sm:flex-row @app-sm:items-center @app-sm:justify-between">
                                <div data-principle="title-subtitle" className="flex flex-col gap-1">
                                    <Typography type="body" weight="semibold">{t("courseCta.title")}</Typography>
                                    <Typography type="body-sm" color="muted">{t("courseCta.body")}</Typography>
                                </div>
                                <Button variant="primary" size="lg" className="shrink-0" onPress={onOpenCourses}>
                                    {t("courseCta.cta")}
                                    <ArrowRightIcon className="size-5" aria-hidden />
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    )
}

import React from "react"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { InfoTooltip } from "@/components/blocks/feedback/InfoTooltip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { FlexWrapButtonRadio } from "@/components/blocks/navigation/FlexWrapButtonRadio"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { ProgressBar } from "@/components/atoms/display/Progress"
import { Container } from "@/components/frames/Container"
import { StackV, StackH } from "@/components/frames/Stack"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { KpiKey } from "@/modules/api/graphql/queries/types/my-kpis"

/** Leading glyph a KPI row carries ΓÇö matches `KPI_META`'s own `Icon` field shape. */
export type KpiRowIcon = React.ComponentType<{ className?: string }>

/** One quick-pick preset target button, already resolved to its disabled state. */
export interface KpiRowPreset {
    /** The preset's target value (e.g. `5`). */
    value: number
    /** `true` while a DIFFERENT preset (on this row or another) is mid-save. */
    isDisabled: boolean
}

/**
 * One weekly-KPI row, fully resolved by the connected {@link KpiPage}: icon + label,
 * current/target, its preset buttons, and its coin-reward claim state.
 */
export interface KpiRowData {
    /** The KPI key (matches BE `KpiKey`) ΓÇö also the React key. */
    key: KpiKey
    /** Leading icon, decorative chrome (not data ΓÇö shown regardless of load state). */
    icon: KpiRowIcon
    /** Already-translated row label. */
    label: string
    /** Current-week value. */
    current: number
    /** Effective target ΓÇö the learner's custom goal, or a sensible default. */
    target: number
    /** Quick-pick target presets, each already carrying its disabled state. */
    presets: Array<KpiRowPreset>
    /** Persist a newly chosen preset target for this row. */
    onChoosePreset: (target: number) => void
    /** Already-translated "N coins" reward line; omitted ΓåÆ no coin-reward row (no target set server-side yet). */
    coinRewardText?: string
    /** `true` ΓåÆ the reward was already claimed this week. */
    claimed: boolean
    /** `true` ΓåÆ the reward is met and not yet claimed (shows the Claim button). */
    canClaim: boolean
    /** `true` while THIS row's claim mutation is in flight. */
    isClaiming: boolean
    /** `true` while a DIFFERENT row's claim mutation is in flight. */
    isClaimDisabled: boolean
    /** Claim this row's coin reward. */
    onClaim: () => void
}

/** All display text, already localized by the connected {@link KpiPage}; a story passes i18n keys. */
export interface KpiLabels {
    /** Page title, also the breadcrumb's current crumb and the info-tooltip heading. */
    title: string
    /** Info-tooltip explanation body for the title. */
    tooltipDescription: string
    /** Breadcrumb root ("Home") label. */
    homeLabel: string
    /** Full composite-score + reset-countdown sentence under the title. */
    description: string
    errorTitle: string
    retry: string
    /** Claim-button label, shared by every row. */
    claimLabel: string
    /** "Claimed" caption, shared by every row. */
    claimedLabel: string
}

/** Props for {@link _KpiPage} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface KpiPageProps {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Truthy ΓåÆ the error message (beats loading). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler ΓÇö paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Navigate to the dashboard (breadcrumb root). */
    onNavigateHome: () => void
    /** The six weekly-KPI rows, in display order. */
    rows: Array<KpiRowData>
    labels: KpiLabels
    /** Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * One row's inner content ΓÇö leading icon + label, current/target, the progress bar,
 * the quick-pick preset buttons, and the coin-reward claim line. `SurfaceCardList`
 * free-form `content` and `FlexWrapButtonRadio` carry no `isSkeleton` of their own
 * (`missingSkeletonSupport`), so the preset row is mirrored inline with `Skeleton.Button`
 * right where it sits rather than built as a second, hand-kept tree.
 */
const kpiRowBody = (row: KpiRowData, isSkeleton: boolean, labels: KpiLabels) => {
    const labelValueRow = () => (
        <StackH justify="between" gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => (
                    <StackH gap={3} principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        items={[
                            () => <row.icon className="size-5 shrink-0 text-foreground" />,
                            () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text={row.label} />,
                        ]}
                    />
                ),
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        classNames={isSkeleton ? ["w-1/4"] : undefined}
                        text={`${row.current}/${row.target}`}
                    />
                ),
            ]}
        />
    )

    const presetRow = () => (
        isSkeleton ? (
            <StackH gap={3} principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                items={row.presets.map((preset) => () => (
                    <Skeleton.Button key={preset.value} width="w-16" />
                ))}
            />
        ) : (
            <FlexWrapButtonRadio
                ariaLabel={row.label}
                value={String(row.target)}
                onChange={(value) => row.onChoosePreset(Number(value))}
                items={row.presets.map((preset) => ({
                    value: String(preset.value),
                    content: preset.value,
                    isDisabled: preset.isDisabled,
                }))}
            />
        )
    )

    const coinRow = () => (
        <StackH justify="between" gap={3} principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            items={[
                () => (
                    <Typography
                        size="xs"
                        color={row.canClaim ? "accent-soft" : "muted"}
                        text={row.coinRewardText as string}
                    />
                ),
                ...(row.claimed
                    ? [() => <Typography size="xs" color="muted" text={labels.claimedLabel} />]
                    : row.canClaim
                        ? [() => (
                            <Button
                                variant="primary"
                                size="sm"
                                isPending={row.isClaiming}
                                isDisabled={row.isClaimDisabled}
                                onPress={row.onClaim}
                                label={labels.claimLabel}
                            />
                        )]
                        : []),
            ]}
        />
    )

    const rowItems = [
        labelValueRow,
        () => (
            <ProgressBar
                ariaLabel={row.label}
                value={row.current}
                max={row.target || 1}
                color="accent"
                size="sm"
                isSkeleton={isSkeleton}
            />
        ),
        presetRow,
        ...(!isSkeleton && row.coinRewardText ? [coinRow] : []),
    ]

    return <StackV gap={4} items={rowItems} />
}

/**
 * The `/kpi` editor page body ΓÇö the presentational half of {@link KpiPage}: the
 * composite score header, then one joined row per weekly KPI (icon ┬╖ label ┬╖
 * current/target ┬╖ progress ┬╖ preset target buttons ┬╖ coin-reward claim).
 * `PageHeader`/`ResponsiveBreadcrumb`/`InfoTooltip` carry no `isSkeleton` of their
 * own (`missingSkeletonSupport`), so the header zone is mirrored inline with
 * `Skeleton.*` right where it sits, rather than a separate hand-kept skeleton tree.
 * See `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch, the mutations,
 * and i18n.
 *
 * @param props - {@link KpiPageProps}
 */
export const _KpiPage = ({
    isSkeleton = false,
    error,
    onRetry,
    onNavigateHome,
    rows,
    labels,
    classNames,
}: KpiPageProps) => {
    // error beats a stale loading flag (BLOCK-8) ΓÇö the shared `AsyncContentError`
    // frame, not hand-written JSX (loading-and-skeleton.md ┬º6).
    if (error) {
        return (
            <AsyncContentError
                title={labels.errorTitle}
                onRetry={onRetry}
                retryLabel={labels.retry}
            />
        )
    }

    const headerZone = () => (
        isSkeleton ? (
            <StackV gap={4} items={[
                () => <Skeleton.Breadcrumbs count={2} />,
                () => <Skeleton.Typography type="h3" width="1/3" />,
                () => <Skeleton.Typography type="body-sm" width="1/2" />,
            ]}
            />
        ) : (
            <PageHeader
                breadcrumb={(
                    <ResponsiveBreadcrumb
                        items={[
                            {
                                key: "home",
                                label: labels.homeLabel,
                                onPress: onNavigateHome,
                            },
                            {
                                key: "kpi",
                                label: labels.title,
                            },
                        ]}
                    />
                )}
                title={(
                    <InfoTooltip title={labels.title} description={labels.tooltipDescription}>
                        {labels.title}
                    </InfoTooltip>
                )}
                description={labels.description}
            />
        )
    )

    return (
        <Container
            identity={{ tier: "page", component: "KpiPage" }}
            size="sm"
            padding={6}
            isSkeleton={isSkeleton}
            classNames={classNames}
            body={() => (
                <StackV gap={7} items={[
                    headerZone,
                    () => {
                        const kpiItems: Array<SurfaceCardListItem> = rows.map((row) => ({
                            key: row.key,
                            content: () => kpiRowBody(row, isSkeleton, labels),
                        }))
                        return <SurfaceCardList items={kpiItems} />
                    },
                ]}
                />
            )}
        />
    )
}

import React from "react"
import type { ReactNode } from "react"
import Link from "next/link"
import {
    TrophyIcon,
} from "@phosphor-icons/react"
import {
    AsyncContentEmpty,
} from "@/components/composites/async/AsyncContent"
import {
    Typography,
} from "@/components/atoms/text/Typography"
import {
    Box,
} from "@/components/frames/Box"
import {
    StackV,
    StackH,
} from "@/components/frames/Stack"
import {
    Skeleton,
} from "@/components/blocks/skeleton/Skeleton"
import {
    UserCell,
} from "@/components/composites/lists/UserCell"
import {
    StandingHeroCard,
    type StandingHeroProgress,
} from "@/components/blocks/dashboard/StandingHeroCard"
import {
    Podium,
} from "@/components/blocks/dashboard/Podium"
import {
    IconTile,
} from "@/components/blocks/identity/IconTile"
import {
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@/components/composites/cards/SurfaceCard"
import {
    FollowButton,
} from "@/components/blocks/community/FollowButton"
import {
    Confetti,
} from "@/components/blocks/dashboard/Confetti"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** How many placeholder rank-4+ rows the co-located skeleton shows. */
const SKELETON_ROW_COUNT = 6

/** One top-3 podium finisher, already resolved (points formatted, "mine" decided). */
export interface GlobalBoardPodiumEntry {
    rank: number
    username: string | null
    avatar: string | null
    /** Already-translated points label, e.g. "1420 XP". */
    pointsLabel: string
    /** True when this finisher is the viewer ΓÇö ring-accent avatar + accent name (`Podium`'s own contract). */
    isMe: boolean
}

/**
 * One rank-4+ row, already resolved: display name already carries the ΓÇö ┬╖ You"
 * suffix when it's the viewer's own row (matches the connected file's old
 * string composition), follow state resolved from the connected file's sets.
 */
export interface GlobalBoardRow {
    key: string
    rank: number
    isMine: boolean
    /** Already composed with the ΓÇö ┬╖ You" suffix when {@link GlobalBoardRow.isMine}. */
    displayName: string
    avatar: string | null
    profileHref: string
    /** Already-translated points label, e.g. "1420 XP". */
    pointsLabel: string
    following: boolean
    isPending: boolean
    onToggleFollow: () => void
}

/** The viewer's own pinned row, appended after an ellipsis when they sit below the fetched slice. */
export interface GlobalBoardSelfRow {
    rank: number
    /** Already composed with the ΓÇö ┬╖ You" suffix (matches the connected file's old string composition). */
    displayName: string
    avatar: string | null
    /** Already-translated points label. */
    pointsLabel: string
}

/** Props for {@link _GlobalBoard} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface GlobalBoardProps extends WithClassNames<undefined> {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no ranked entries ΓåÆ the empty message (funnel to courses). */
    isEmpty?: boolean

    /** Rank-driven badge art for the standing hero (`rankBadgeIcon`) ΓÇö already a built node (block API). */
    rankBadge?: ReactNode
    /** e.g. "Rank #9 platform-wide". */
    rankLabel?: string
    /** e.g. "1420 XP". */
    pointsMeta?: string
    /** Goal-gradient meter toward the next rank; omitted when the viewer is already #1 or has no baseline. */
    progress?: StandingHeroProgress
    /** North-star CTA label ΓÇö funnels to courses. Shown on the hero and (as the retry action) on the empty state. */
    climbCtaLabel: string
    onClimb: () => void

    /** Top-3 finishers for the podium. */
    podiumEntries?: Array<GlobalBoardPodiumEntry>
    /** "You" suffix label for the podium's own finisher. */
    meLabel: string

    /** Rank 4+ rows. Shown whenever there's more than the podium, or the viewer sits below it. */
    rows?: Array<GlobalBoardRow>
    /** Whether the rank-4+ section renders at all (mirrors the connected file's old gate). */
    showRows?: boolean
    /** Pinned self-row appended after an ellipsis when the viewer sits below the fetched slice. */
    selfRow?: GlobalBoardSelfRow
    /** "{count} more" between the fetched slice and the pinned self-row; omitted when there's no gap. */
    hiddenBetweenLabel?: string

    /** Bumped to fire a confetti burst on a top-3 platform finish. */
    celebrateKey?: number

    emptyTitle: string
    emptyDescription: string
}

/**
 * The global (all-users) leaderboard ΓÇö presentational half of {@link import("./index").GlobalBoard}.
 * Same shell as the weekly board: a {@link StandingHeroCard} of the viewer's platform-wide standing,
 * the top-3 {@link Podium}, then rank 4+ as a followable {@link SurfaceCardList}. `isSkeleton`
 * threads down to every leaf; `StandingHeroCard`/`Podium`/`IconTile`/`SurfaceCardList`/`FollowButton`/
 * `UserCell` take no `isSkeleton` of their own (`missingSkeletonSupport`), so each is mirrored in
 * place with `Skeleton.*` at the exact position it renders, instead of a parallel skeleton tree. See
 * `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch, the follow mutation, and every label.
 *
 * @param props - {@link GlobalBoardProps}
 */
export const _GlobalBoard = ({
    className,
    isSkeleton = false,
    isEmpty = false,
    rankBadge,
    rankLabel,
    pointsMeta,
    progress,
    climbCtaLabel,
    onClimb,
    podiumEntries = [],
    meLabel,
    rows = [],
    showRows = false,
    selfRow,
    hiddenBetweenLabel,
    celebrateKey = 0,
    emptyTitle,
    emptyDescription,
}: GlobalBoardProps) => {
    // settled, nothing to rank yet ΓåÆ funnel to courses (BLOCK-8: error/loading beat empty; this
    // component has no distinct error state ΓÇö an SWR error settles with `!data`, which the
    // connected file already folds into `isEmpty`, exactly like the retired `AsyncContent` did).
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                icon={TrophyIcon}
                title={emptyTitle}
                description={emptyDescription}
                onRetry={onClimb}
                retryLabel={climbCtaLabel}
            />
        )
    }

    const podiumRows = isSkeleton
        ? [false, true, false]
        : podiumEntries.slice(0, 3).map((entry) => entry.rank === 1)
    const skeletonRows = Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => index)

    // `StackV`'s own `classNames` is the closed positioning-only allowlist (ATOM-4 vocabulary),
    // not a free-form passthrough ΓÇö an incoming placement `className` from the caller needs the
    // frame tier's escape hatch (`Box`), which is the ONLY frame that takes a raw string.
    return (
        <Box className={className}>
            <StackV
                gap={6}
                principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                identity={{ tier: "block", component: "GlobalBoard" }}
                items={[
                    // celebrate a top-3 platform finish ΓÇö only meaningful once real data has settled
                    ...(!isSkeleton ? [() => <Confetti fireKey={celebrateKey} />] : []),

                    // ΓöÇΓöÇ your platform-wide standing ΓöÇΓöÇ `StandingHeroCard` has no `isSkeleton` of its
                    // own (missingSkeletonSupport): mirrored in place with `Skeleton.*`, same box.
                    () => (isSkeleton ? (
                        <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
                            explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
                            <StackV gap={5} principle="group-boundary"
                                explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                items={[
                                    () => (
                                        <StackH gap={5} principle="group-boundary"
                                            explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                                            align="center" items={[
                                                () => <Skeleton className="size-10 shrink-0 rounded-2xl" />,
                                                () => (
                                                    <StackV gap={2} principle="title-subtitle"
                                                        explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                                        classNames={["min-w-0", "flex-1"]} items={[
                                                            () => <Skeleton.Typography type="h6" width="1/2" />,
                                                            () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                                        ]} />
                                                ),
                                            ]} />
                                    ),
                                    () => (
                                        <StackV gap={2} principle="title-subtitle"
                                            explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                            items={[
                                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                                () => <Skeleton.ProgressBar />,
                                            ]} />
                                    ),
                                    () => <Skeleton className="h-10 w-40 rounded-full" />,
                                ]} />
                        </Box>
                    ) : (
                        <StandingHeroCard
                            badge={rankBadge ? <IconTile icon={rankBadge} tone="neutral" size="sm" /> : undefined}
                            rankLabel={rankLabel}
                            meta={pointsMeta}
                            progress={progress}
                            ctaLabel={climbCtaLabel}
                            onCta={onClimb}
                        />
                    )),

                    // ΓöÇΓöÇ the winners' dais ΓöÇΓöÇ `Podium` has no `isSkeleton` of its own
                    // (missingSkeletonSupport): mirrored in place, champion centered + raised.
                    () => (isSkeleton ? (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            align="end" justify="center" items={podiumRows.map((isChampion) => () => (
                                <StackV gap={2} principle="title-subtitle"
                                    explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                    align="center" items={[
                                        () => <Skeleton className={isChampion ? "size-14 shrink-0 rounded-full" : "size-12 shrink-0 rounded-full"} />,
                                        () => (
                                            <StackV gap={2} principle="title-subtitle"
                                                explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                                align="center" classNames={["w-full"]} items={[
                                                    () => <Skeleton.Typography type="body-sm" width="3/4" />,
                                                    () => <Skeleton.Typography type="body-xs" width="1/2" />,
                                                ]} />
                                        ),
                                        () => (
                                            <Box className={isChampion
                                                ? "h-16 w-20 rounded-t-2xl rounded-b-none"
                                                : "h-10 w-20 rounded-t-2xl rounded-b-none"}
                                            >
                                                <Skeleton className="h-full w-full rounded-t-2xl rounded-b-none" />
                                            </Box>
                                        ),
                                    ]} />
                            ))} />
                    ) : (
                        <Podium
                            meLabel={meLabel}
                            entries={podiumEntries.map((entry) => ({
                                rank: entry.rank,
                                username: entry.username,
                                avatar: entry.avatar,
                                pointsLabel: entry.pointsLabel,
                                isMe: entry.isMe,
                            }))}
                        />
                    )),

                    // ΓöÇΓöÇ rank 4+ ΓöÇΓöÇ a followable list; `SurfaceCardList`/`FollowButton`/`UserCell`
                    // have no `isSkeleton` of their own (missingSkeletonSupport): each row is
                    // mirrored in place with `Skeleton.UserCell` + bare bars, same row shape.
                    ...(isSkeleton || showRows ? [() => {
                        const listItems: Array<SurfaceCardListItem> = isSkeleton
                            ? skeletonRows.map((row) => ({
                                key: `skeleton-${row}`,
                                content: () => (
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                            () => <Skeleton.UserCell className="min-w-0 flex-1" withHandle={false} />,
                                            () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                        ]} />
                                ),
                            }))
                            : [
                                ...rows.map((row) => ({
                                    key: row.key,
                                    content: () => (
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => (
                                                    <Box className="w-6 shrink-0">
                                                        <Typography
                                                            size="xs"
                                                            align="end"
                                                            color={row.isMine ? "accent" : "muted"}
                                                            weight={row.isMine ? "semibold" : undefined}
                                                            text={String(row.rank)}
                                                        />
                                                    </Box>
                                                ),
                                                () => (
                                                    <Link
                                                        href={row.profileHref}
                                                        className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                                                    >
                                                        <UserCell username={row.displayName} avatar={row.avatar} />
                                                    </Link>
                                                ),
                                                () => (
                                                    <Typography
                                                        size="sm"
                                                        color={row.isMine ? "accent" : "muted"}
                                                        weight={row.isMine ? "semibold" : undefined}
                                                        classNames={["shrink-0"]}
                                                        text={row.pointsLabel}
                                                    />
                                                ),
                                                ...(!row.isMine ? [() => (
                                                    <FollowButton
                                                        quiet
                                                        following={row.following}
                                                        isPending={row.isPending}
                                                        onToggle={row.onToggleFollow}
                                                    />
                                                )] : []),
                                            ]} />
                                    ),
                                })),
                                // viewer below the fetched slice ΓåÆ ellipsis + pinned self-row
                                ...(selfRow
                                    ? [
                                        {
                                            key: "hidden-between",
                                            content: () => (
                                                <Box principle="control-pad" className="-m-3 bg-surface-secondary px-3 py-2 text-xs text-muted"
                                                    explain="Control hit-area inset ΓÇö not row-pad, because this pads a single interactive control rather than a full content row.">
                                                    <StackH gap={3} principle="sibling-stack"
                                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                        align="center" justify="center" items={[
                                                            () => <span className="text-base leading-none tracking-widest">Γï»</span>,
                                                            ...(hiddenBetweenLabel ? [() => <Typography size="xs" color="muted" text={hiddenBetweenLabel} />] : []),
                                                        ]} />
                                                </Box>
                                            ),
                                        },
                                        {
                                            key: "self-row",
                                            content: () => (
                                                <StackH gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    align="center" items={[
                                                        () => (
                                                            <Box className="w-6 shrink-0">
                                                                <Typography size="xs" align="end" color="accent" weight="semibold" text={String(selfRow.rank)} />
                                                            </Box>
                                                        ),
                                                        () => (
                                                            <Box className="min-w-0 flex-1">
                                                                <UserCell username={selfRow.displayName} avatar={selfRow.avatar} />
                                                            </Box>
                                                        ),
                                                        () => (
                                                            <Typography size="sm" color="accent" weight="semibold" classNames={["shrink-0"]} text={selfRow.pointsLabel} />
                                                        ),
                                                    ]} />
                                            ),
                                        },
                                    ]
                                    : []),
                            ]

                        return <SurfaceCardList items={listItems} />
                    }] : []),
                ]}
            />
        </Box>
    )
}

import React from "react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { StandingHeroCard } from "@/components/blocks/dashboard/StandingHeroCard"
import { Podium, type PodiumEntry } from "@/components/blocks/dashboard/Podium"
import { rankBadgeIcon } from "@/components/blocks/dashboard/rankBadge"
import { Confetti } from "@/components/blocks/dashboard/Confetti"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackV, StackH } from "@/components/frames/Stack"

/** Number of placeholder cohort rows (rank 4+) shown while the board shimmers. */
const SKELETON_ROW_COUNT = 6

/** "Your standing" hero ΓÇö already resolved (i18n interpolated) by the connected `WeeklyBoard`. */
export interface WeeklyBoardHero {
    /** 1-based rank, drives the {@link rankBadgeIcon} art. */
    rank: number
    /** Primary line, e.g. "Rank #1 ┬╖ Bronze" (already translated + interpolated). */
    rankLabel: string
    /** Secondary meta line ΓÇö points ┬╖ reset countdown (already translated + interpolated). */
    meta: string
    /** Optional goal-gradient meter toward the promotion cutoff. */
    progress?: {
        /** Fill ratio, `0..1`. */
        ratio: number
        /** Muted line above the meter (already translated + interpolated). */
        label: string
    }
}

/** One top-3 podium finisher ΓÇö see {@link PodiumEntry}. */
export type WeeklyBoardPodiumEntry = PodiumEntry

/** One rank 4+ cohort row, already resolved by the connected `WeeklyBoard`. */
export interface WeeklyBoardRowEntry {
    /** Stable row identity. */
    userGlobalId: string
    /** 1-based rank. */
    rank: number
    /** True when this row is the viewer's own. */
    mine: boolean
    /** Resolved, locale-aware link to this user's public profile. */
    profileHref: string
    /** Display username ΓÇö the viewer's own row already carries the "┬╖ you" suffix. */
    displayUsername: string
    /** Avatar URL, or `null` for the generated fallback. */
    avatar: string | null
    /** Pre-formatted points label (already translated). */
    pointsLabel: string
    /** Weekly rank movement (`>0` climbed, `<0` dropped, `0`/`null` unchanged/no baseline). */
    rankDelta: number | null
}

/** All display text, already localized by the connected `WeeklyBoard`; a story passes i18n keys. */
export interface WeeklyBoardLabels {
    /** Nothing to show until the viewer is placed in a cohort ΓÇö funnel-to-courses title. */
    emptyTitle: string
    /** Funnel-to-courses supporting line under {@link WeeklyBoardLabels.emptyTitle}. */
    emptyDescription: string
    /** North-star CTA ΓÇö shown both on the hero and as the empty-state retry action. */
    climbCta: string
    /** "you" suffix appended to the viewer's own podium finisher. */
    you: string
    /** Promote-zone legend line (already interpolated with the cohort's promote count). */
    legendPromote: string
    /** Demote-zone legend line (already interpolated with the cohort's demote count). */
    legendDemote: string
}

/** Props for {@link _WeeklyBoard} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface WeeklyBoardProps {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no cohort placement ΓåÆ the empty message (funnel to courses). */
    isEmpty?: boolean
    /** The viewer's own standing hero ΓÇö omitted when the viewer isn't placed in the loaded cohort. */
    hero?: WeeklyBoardHero
    /** Top-3 finishers, best ΓåÆ worst. */
    podiumEntries?: ReadonlyArray<WeeklyBoardPodiumEntry>
    /** Rank 4+ rows ΓÇö the runners the podium can't hold. */
    rows?: ReadonlyArray<WeeklyBoardRowEntry>
    /** Bumped to fire a top-3 confetti burst (owned by the connected file's one-shot effect). */
    celebrateKey?: number
    /** North-star funnel ΓÇö both the hero CTA and the empty-state retry action. */
    onClimb: () => void
    labels: WeeklyBoardLabels
    className?: string
}

/**
 * Loading placeholder for the "your standing" hero ΓÇö mirrors {@link StandingHeroCard}'s shape
 * (badge ┬╖ rank/meta lines ┬╖ goal meter ┬╖ CTA) since the block has no `isSkeleton` of its own.
 */
const HeroSkeleton = () => (
    <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
        explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
        <StackV gap={5} principle="group-boundary"
            explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
            items={[
                () => (
                    <StackH gap={5} principle="group-boundary"
                        explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            () => <Skeleton className="size-10 shrink-0 rounded-2xl" />,
                            () => <StackV gap={2} principle="title-subtitle"
                                explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                classNames={["min-w-0", "flex-1"]} items={[
                                    () => <Skeleton.Typography type="h6" width="1/2" />,
                                    () => <Skeleton.Typography type="body-sm" width="1/3" />,
                                ]} />,
                        ]} />
                ),
                () => (
                    <StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                        items={[
                            () => <Skeleton.Typography type="body-xs" width="1/3" />,
                            () => <Skeleton.ProgressBar />,
                        ]} />
                ),
                () => <Skeleton className="h-10 w-40 rounded-full" />,
            ]} />
    </Box>
)

/**
 * Loading placeholder for the top-3 dais ΓÇö mirrors {@link Podium}'s shape (champion centered +
 * raised) since the block has no `isSkeleton` of its own.
 */
const PodiumSkeleton = () => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        justify="center" items={[false, true, false].map((isChampion) => () => (
            <StackV gap={3} principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                align="center" items={[
                    () => <Skeleton className={isChampion ? "size-14 shrink-0 rounded-full" : "size-12 shrink-0 rounded-full"} />,
                    // The podium column's fixed width is not a member of the closed AllowedClassName
                    // union, so it sits on Box ΓÇö the frame tier's sanctioned escape hatch ΓÇö rather than
                    // widening that union for one skeleton.
                    () => <Box className="w-20"><StackV gap={2} principle="title-subtitle"
                        explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                        align="center" items={[
                            () => <Skeleton.Typography type="body-sm" width="3/4" />,
                            () => <Skeleton.Typography type="body-xs" width="1/2" />,
                        ]} /></Box>,
                    () => <Skeleton className={isChampion ? "h-16 w-20 rounded-t-2xl rounded-b-none" : "h-10 w-20 rounded-t-2xl rounded-b-none"} />,
                ]} />
        ))} />
)

/** Loading placeholder for one rank 4+ row ΓÇö mirrors the [rank ┬╖ avatar ┬╖ name ┬╖ points ┬╖ caret] shape. */
const RowSkeleton = () => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
            () => <Skeleton.Avatar size="sm" />,
            () => <Skeleton.Typography type="body-sm" width="1/3" className="min-w-0 flex-1" />,
            () => <Skeleton className="h-3 w-8 shrink-0 rounded-sm" />,
            () => <Skeleton className="h-4 w-8 shrink-0 rounded-sm" />,
        ]} />
)

/** One resolved rank 4+ row: rank cell ┬╖ profile-linked user cell ┬╖ points ┬╖ movement caret. */
const Row = ({ row }: { row: WeeklyBoardRowEntry }) => (
    <StackH gap={4} principle="content-row"
        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
        items={[
            () => (
                <Box as="span" className="w-6 shrink-0 text-right">
                    <Typography size="xs" color={row.mine ? "accent" : "muted"} weight={row.mine ? "semibold" : undefined} text={String(row.rank)} />
                </Box>
            ),
            () => (
                <Box className="min-w-0 flex-1">
                    <UserCell username={row.displayUsername} avatar={row.avatar} isOwnRow={row.mine } />
                </Box>
            ),
            () => (
                <Typography size="sm" color={row.mine ? "accent" : "muted"} weight={row.mine ? "semibold" : undefined} classNames={["shrink-0"]} text={row.pointsLabel} />
            ),
            () => <RankDeltaCaret delta={row.rankDelta} className="w-8 shrink-0 justify-end" />,
        ]} />
)

/**
 * `_WeeklyBoard` ΓÇö the presentational half of {@link import("./index").WeeklyBoard}: the full
 * weekly-league board shell shared with the global board ΓÇö a {@link StandingHeroCard} of the
 * viewer's own standing, the top-3 {@link Podium}, the promote/demote legend, then rank 4+ in a
 * {@link SurfaceCardList}. Renders ONE tree with `isSkeleton` threaded to every leaf that supports
 * it; the sub-blocks that don't ({@link StandingHeroCard}, {@link Podium}, {@link SurfaceCardList},
 * {@link UserCell}, {@link RankDeltaCaret}) are mirrored in place with `Skeleton.*` at the exact
 * site they render, so the shimmer stays co-located instead of a hand-kept parallel tree
 * (`loading-and-skeleton.md`). See `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch,
 * the async decisions, and every interpolated string.
 *
 * @param props - {@link WeeklyBoardProps}
 */
export const _WeeklyBoard = ({
    isSkeleton = false,
    isEmpty = false,
    hero,
    podiumEntries = [],
    rows = [],
    celebrateKey = 0,
    onClimb,
    labels,
    className,
}: WeeklyBoardProps) => {
    // empty only once settled ΓÇö a first-load skeleton always wins over a structurally-empty isEmpty.
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                title={labels.emptyTitle}
                description={labels.emptyDescription}
                onRetry={onClimb}
                retryLabel={labels.climbCta}
            />
        )
    }

    const showHero = isSkeleton || Boolean(hero)
    const showPodium = isSkeleton || podiumEntries.length > 0
    const showRows = isSkeleton || rows.length > 0

    const listItems: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
            key: `pending-${index}`,
            content: () => <RowSkeleton />,
        }))
        : rows.map((row) => ({
            key: row.userGlobalId,
            href: row.profileHref,
            withVerdict: {
                enable: (row.rankDelta ?? 0) !== 0,
                variant: (row.rankDelta ?? 0) > 0 ? "success" : "danger",
            },
            content: () => <Row row={row} />,
        }))

    return (
        <Box className={className} identity={{ tier: "block", component: "WeeklyBoard" }}>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => <Confetti fireKey={celebrateKey} />,

                    // your standing hero ΓÇö rank-driven badge ┬╖ rank/meta ┬╖ goal meter ┬╖ CTA
                    ...(showHero ? [() => (
                        isSkeleton || !hero
                            ? <HeroSkeleton />
                            : (
                                <StandingHeroCard
                                    badge={<IconTile icon={rankBadgeIcon(hero.rank)} tone="neutral" size="sm" />}
                                    rankLabel={hero.rankLabel}
                                    meta={hero.meta}
                                    progress={hero.progress}
                                    ctaLabel={labels.climbCta}
                                    onCta={onClimb}
                                />
                            )
                    )] : []),

                    // the winners' dais ΓÇö top-3 (viewer's own column ringed)
                    ...(showPodium ? [() => (
                        isSkeleton
                            ? <PodiumSkeleton />
                            : <Podium meLabel={labels.you} entries={[...podiumEntries]} />
                    )] : []),

                    // promote / demote legend
                    () => (
                        <StackH gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <StackH gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Box as="span" className="size-2 shrink-0 rounded-full bg-success" />,
                                            () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.legendPromote} />,
                                        ]} />
                                ),
                                () => (
                                    <StackH gap={3} principle="sibling-stack"
                                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                        items={[
                                            () => <Box as="span" className="size-2 shrink-0 rounded-full bg-danger" />,
                                            () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={labels.legendDemote} />,
                                        ]} />
                                ),
                            ]} />
                    ),

                    // rank 4+ ΓÇö the runners the podium can't hold; zone edge-markers via `withVerdict`
                    ...(showRows ? [() => <SurfaceCardList items={listItems} />] : []),
                ]} />
        </Box>
    )
}

"use client"

import React, {
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    WeeklyBoard,
} from "./WeeklyBoard"
import {
    GlobalBoard,
} from "./GlobalBoard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { StackV } from "@/components/frames/Stack"
import { pathConfig } from "@/resources/path"
/** The two leaderboard scopes the page can show. */
enum LeagueTab {
    Weekly = "weekly",
    Global = "global",
}

/** Props for {@link LeaguePage}. */
export type LeaguePageProps = Record<string, never>
/**
 * The full leaderboard page behind the dashboard `LeagueCard`'s "see more":
 * a proper main page ({@link PageHeader} + responsive breadcrumb, per
 * `header.md` ΓÇö no bare `<h1>`) with two page-level tabs ΓÇö the weekly-league
 * cohort ("this week") and the global all-users board ("global"). The tabs
 * switch the WHOLE board panel, so they're a `TabsCard variant="primary"`
 * segmented pill (`tabs.md ┬º0b`), not a filter underline. Each board
 * self-fetches; only the active one mounts (the inactive leaf query stays
 * idle). `"use client"` for tab state + breadcrumb nav.
 *
 * @param props - optional className for the root element.
 */
export const LeaguePage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const [tab, setTab] = useState<LeagueTab>(LeagueTab.Weekly)

    return (
        <div className={"mx-auto w-full max-w-2xl p-3"} data-principle="cell-pad">
            <StackV
                principle="layout-split"
                explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                items={[
                    () => (
                        <PageHeader
                            breadcrumb={(
                                <ResponsiveBreadcrumb
                                    items={[
                                        {
                                            key: "home",
                                            label: t("nav.home"),
                                            onPress: () => router.push(pathConfig().locale(locale).build()),
                                        },
                                        { key: "league", label: t("dashboard.league.pageTitle") },
                                    ]}
                                />
                            )}
                            title={t("dashboard.league.pageTitle")}
                        />
                    ),
                    // tabs + board grouped at block-boundary; only the active board mounts
                    () => (
                        <StackV
                            principle="block-boundary"
                            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                            items={[
                                () => (
                                    <TabsCard
                                        variant="primary"
                                        leftTabs={{
                                            items: [
                                                { key: LeagueTab.Weekly, label: t("dashboard.league.tabWeekly") },
                                                { key: LeagueTab.Global, label: t("dashboard.league.tabGlobal") },
                                            ],
                                            selectedKey: tab,
                                            ariaLabel: t("dashboard.league.pageTitle"),
                                            onSelectionChange: (key) => setTab(String(key) as LeagueTab),
                                        }}
                                    />
                                ),
                                () => (tab === LeagueTab.Weekly ? <WeeklyBoard /> : <GlobalBoard />),
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )
}

"use client"

import React from "react"
import {
    Breadcrumbs,
    Button,
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import {
    PRIVACY_LAST_UPDATED,
    PRIVACY_POLICY,
    TERMS_LAST_UPDATED,
    TERMS_OF_SERVICE,
} from "@/resources/legal"
import type {
    LegalSection,
} from "@/resources/legal"
import { PageContainer } from "@/components/blocks/layout/PageContainer"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Which legal document this page renders. */
export type LegalKind = "terms" | "privacy"

/** Props for {@link LegalPage}. */
export interface LegalPageProps {
    /** Selects the legal document (and its `legal.*` header copy) to render. */
    kind: LegalKind
}

/** Props for the in-page {@link Section} renderer. */
interface SectionProps {
    /** One numbered legal section from the structured document. */
    section: LegalSection
}

/**
 * Renders one numbered section: heading + body paragraphs + an optional bullet
 * list whose items may carry a bold lead label. Plain Typography ΓÇö no markdown.
 */
const Section = ({ section }: SectionProps) => {
    const sectionItems = [
        () => <Typography.Heading level={4} weight="semibold">{section.heading}</Typography.Heading>,
        ...(section.paragraphs?.map((paragraph) => () => (
            <Typography key={paragraph} type="body" color="muted" className="leading-relaxed">
                {paragraph}
            </Typography>
        )) ?? []),
        ...(section.items
            ? [() => (
                <ul data-principle="sibling-stack" className="flex flex-col gap-2">
                    {section.items!.map((item) => (
                        <li key={item.label ?? item.text} data-principle="icon-text" className="flex gap-2">
                            <span className="mt-2 size-1.5 shrink-0 rounded-full bg-default-400" aria-hidden />
                            <Typography type="body" color="muted" className="leading-relaxed">
                                {item.label ? (
                                    <span className="font-semibold text-foreground">{`${item.label} `}</span>
                                ) : null}
                                {item.text}
                            </Typography>
                        </li>
                    ))}
                </ul>
            )]
            : []),
    ]
    return (
        <StackV as="section" gap={4} items={sectionItems} />
    )
}

/**
 * Shared legal document page (`/terms`, `/privacy`): a 3-tier reading column ΓÇö
 * breadcrumb ΓåÆ `PageHeader` (title + description + last-updated) ΓåÆ the document
 * rendered NATIVELY from structured content (numbered sections of paragraphs and
 * bullet lists) with Typography. No markdown. Document picked by `kind` + the
 * active locale (falls back to `vi`); copy lives in `legal/content/{privacy,terms}.ts`.
 *
 * @param props - {@link LegalPageProps}
 */
export const LegalPage = ({ kind }: LegalPageProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const docs = kind === "privacy" ? PRIVACY_POLICY : TERMS_OF_SERVICE
    const doc = docs[locale] ?? docs.vi
    const lastUpdatedIso = kind === "privacy" ? PRIVACY_LAST_UPDATED : TERMS_LAST_UPDATED
    // local-midnight parse avoids a timezone day-shift; localized long date
    const lastUpdated = new Date(`${lastUpdatedIso}T00:00:00`).toLocaleDateString(
        locale === "vi" ? "vi-VN" : "en-GB",
        { day: "numeric", month: "long", year: "numeric" },
    )

    const docItems = [
        () => (
            <Typography type="body" className="leading-relaxed">
                {doc.intro}
            </Typography>
        ),
        ...doc.sections.map((section) => () => (
            <Section key={section.heading} section={section} />
        )),
    ]

    return (
        <PageContainer>
            <Box principle="center-measure" className="mx-auto max-w-3xl"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <StackV gap={7} principle="layout-split"
                    explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={(
                                    <Breadcrumbs>
                                        <Breadcrumbs.Item onPress={() => router.push(pathConfig().locale().build())}>
                                            {t("nav.home")}
                                        </Breadcrumbs.Item>
                                        <Breadcrumbs.Item>
                                            {t(`legal.${kind}.title`)}
                                        </Breadcrumbs.Item>
                                    </Breadcrumbs>
                                )}
                                title={t(`legal.${kind}.title`)}
                                description={t(`legal.${kind}.description`)}
                                meta={(
                                    <Typography type="body-xs" color="muted">
                                        {t("legal.lastUpdated", { date: lastUpdated })}
                                    </Typography>
                                )}
                            />
                        ),
                        () => <StackV gap={7} principle="layout-split"
                            explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                            items={docItems} />,
                        () => (
                            <Button
                                variant="tertiary"
                                size="sm"
                                className="self-start"
                                onPress={() => router.push(pathConfig().locale().course().build())}
                            >
                                {`${t("cart.browseCourses")} ΓåÆ`}
                            </Button>
                        ),
                    ]} />
            </Box>
        </PageContainer>
    )
}
